	//if (damage - mpEquipmentManager->GetDamage() <= 0) { hp_ -= 1; return; }//鬯ｮｽｫ繝ｻｽｴ髯晢ｽｷ郢晢ｽｻ陷托ｽｲ鬮ｯ貊捺ｱ壹ｻｽｽ繝ｻｽｱ鬩搾ｽｵ繝ｻｽｲ髯懶ｽ｣繝ｻｽ､郢晢ｽｻ繝ｻｽｹ郢晢ｽｻ繝ｻｽｧ鬩幢ｽ｢繝ｻｽｧ鬮｣魃会ｽｽｽｨ郢晢ｽｻ繝ｻｽｽ郢晢ｽｻ繝ｻｽｸ鬮ｯ譎｢ｽｽｽｶ髯ｷｽｻ繝ｻｽｻ郢晢ｽｻ繝ｻｽｽ鬮｢ｽｾ繝ｻｽ･郢晢ｽｻ繝ｻｽｸ郢晢ｽｻ繝ｻｽｺ鬩幢ｽ｢隴趣ｽ｢繝ｻｽｽ繝ｻｽｻ
	if (now == ANIMATION_SLIDE || now == ANIMATION_ATTACKSLIDE)return;
	hp_ -= (damage-mpEquipmentManager->GetDamage());//鬯ｯｽｮ繝ｻｽｯ郢晢ｽｻ繝ｻｽｬ鬩幢ｽ｢隴趣ｽ｢繝ｻｽｽ繝ｻｽｻE鬯ｩ謳ｾｽｽｽｵ郢晢ｽｻ繝ｻｽｺ鬮ｯｽｷ闔ｨ螟ｲｽｽｽｽ繝ｻｽｱ鬩包ｽｯ繝ｻｽｶ郢晢ｽｻ繝ｻｽｻ鬯ｩ謳ｾｽｽｽｵ郢晢ｽｻ繝ｻｽｺ鬩幢ｽ｢隴趣ｽ｢繝ｻｽｽ繝ｻｽｻE鬯ｩ蟷｢ｽｽｽ｢髫ｴ諠ｹｽｼ螟ｲｽｽｽｽ繝ｻｽｹ髫ｴ雜｣ｽｽｽ｢郢晢ｽｻ繝ｻｽｽ郢晢ｽｻ繝ｻｽ｡鬯ｩ蟷｢ｽｽｽ｢髫ｴ雜｣ｽｽｽ｢郢晢ｽｻ繝ｻｽｽ郢晢ｽｻ繝ｻｽｼ鬯ｩ蟷｢ｽｽｽ｢郢晢ｽｻ繝ｻｽｧE鬯ｮｽｯ陷茨ｽｷ繝ｻｽｽ繝ｻｽｻ鬩幢ｽ｢隴趣ｽ｢繝ｻｽｽ繝ｻｽｻ鬩幢ｽ｢隴趣ｽ｢繝ｻｽｿ繝ｻｽｽ鬯ｩ蟷｢ｽｽｽ｢髫ｴ雜｣ｽｽｽ｢郢晢ｽｻ繝ｻｽｽ郢晢ｽｻ繝ｻｽ｡鬯ｩ蟷｢ｽｽｽ｢髫ｴ雜｣ｽｽｽ｢郢晢ｽｻ繝ｻｽｽ郢晢ｽｻ繝ｻｽｼ鬯ｩ蟷｢ｽｽｽ｢郢晢ｽｻ繝ｻｽｧE鬯ｩ蟷｢ｽｽｽ｢郢晢ｽｻ繝ｻｽｧ鬮ｯｽｷ繝ｻｽｻ鬮｣魃会ｽｽｽｨ郢晢ｽｻ繝ｻｽｽ郢晢ｽｻ繝ｻｽｸ鬮ｯ譎｢ｽｽｽｶ髯ｷｽｻ繝ｻｽｻ郢晢ｽｻ繝ｻｽｽ鬮｢ｽｾ繝ｻｽ･郢晢ｽｻ繝ｻｽｸ郢晢ｽｻ繝ｻｽｺ鬩幢ｽ｢隴趣ｽ｢繝ｻｽｽ繝ｻｽｻ

