void Player3D::if_StageOut()
{
	float radiusX = Config::StageRadius_x; // X隴ｽｹ陷ｷ謇假ｽｼ蝓滂ｽｨｽｪ繝ｻ蟲ｨ繝ｻ鬮ｯ蜊髦懃ｸｺｽｮ陟弱ｻｼ
	float radiusZ = Config::StageRadius_z; // Z隴ｽｹ陷ｷ謇假ｽｼ莠･ｽ･ｽ･繝ｻ蟲ｨ繝ｻ鬮ｯ蜊髦懃ｸｺｽｮ陟弱ｻｼ
	auto scene = Master::mpSceneManager->GetCurrentScene();
	SceneGame* game = Master::mpSceneManager->GetSceneGame();
	VECTOR centerPos;//stage縺ｮ逵溘ｓ荳ｭ
	if (game->mpGameManager->GetCurrentPhase() == GameManager::Phase::BOSS)
	{
		centerPos = Config::GetStageBossCenter();//遨ｺ荳ｭ蟲ｶ縺ｮ逵溘ｓ荳ｭ縺ｮ蝨ｰ轤ｹ
		radiusX = Config::BossStageRadius;
		radiusZ = Config::BossStageRadius;//boss繧ｹ繝繝ｼ繧ｸ縺ｮ蜊雁ｾ
	}
	else
	{
		centerPos = VGet(Config::GetStageCenter().x, 0, Config::GetStageCenter().z);//騾壼ｸｸ縺ｮ繧ｹ繝繝ｼ繧ｸ荳ｭ螟ｮ
	}
	float dx = position_.x - centerPos.x;
	float dz = position_.z - centerPos.z;
	//邵ｺ譏ｴｽ檎ｸｺ讒ｭｽ檎ｸｺｽｮ陷企宦ｽｾ繝ｻ縲定恆ｽｲ邵ｺｽ｣邵ｺｽｦ邵ｲ竏ｽｽｸﾂ隴弱ｉ蝎ｪ邵ｺｽｫ邵ｲ謔滓ｿ陟輔ｻ邵ｺｽｮ騾ｵ貅假ｽ楢叉ｽｸ邵ｺｽｪ陷繝ｻﾂ髦ｪ繝ｻ闕ｳ荵滄懃ｸｺｽｫ陞溽判驪､邵ｺ蜷ｶｽ
	float normX = dx / radiusX;
	float normZ = dz / radiusZ;
	//邵ｺ譏ｴ繝ｻ邵ｲ謔滓ｿ陟輔ｻ邵ｺｽｮ陷繝ｻﾂ髦ｪ繝ｻ闕ｳ荵滄懃ｸｺｽｧ邵ｺｽｮ邵ｲ竏ｽｽｸｽｭ陟｢繝ｻﾂｰ郢ｧ蟲ｨ繝ｻ髴肴辨螻ｬ郢ｧ螳夲ｽｨ閧ｲｽｮ蜉ｱ笘郢ｧ繝ｻ
	float distance = sqrtf(normX * normX + normZ * normZ);
	//髴肴辨螻ｬ邵ｺ繝ｻ1.0 郢ｧ螳夲ｽｶ繝ｻ竏ｴ邵ｺｽｦ邵ｺ繝ｻ笳郢ｧ莨夲ｽｼ蝓滂ｽ･蜍溘ｻ邵ｺｽｮ陞滓じ竊鍋ｸｺｽｯ邵ｺｽｿ陷ｽｺ邵ｺ蜉ｱ窶ｻ邵ｺ繝ｻ笳郢ｧ莨夲ｽｼ繝ｻ
	if (distance > 1.0f)
	{
		position_ = old_position_;//map螟悶↓蜃ｺ縺溘ｉ菴咲ｽｮ蠎ｧ讓吶ｒ謌ｻ縺
	}
	

}

void Player3D::Evasion()
{
	if (InputManager::CheckDownKey(KEY_INPUT_SPACE))
	{
		if (model_->GetIsSeparate())model_->mpSeparateAnimation->SetAnimationCount(1.2f);
		else model_->mpAnimation->SetAnimationCount(1.2f);
		model_->ChangeAnimation(ANIMATION_SLIDE);
		model_->SetLoop(false);
		model_->SetLoopFinishState(ANIMATION_NEUTRAL);
		
		// 鬯ｩ蟷｢ｽｽｽ｢郢晢ｽｻ繝ｻｽｧE鬯ｩ蟷｢ｽｽｽ｢髫ｴ雜｣ｽｽｽ｢郢晢ｽｻ繝ｻｽｽ郢晢ｽｻ繝ｻｽｩ鬯ｩ蟷｢ｽｽｽ｢郢晢ｽｻ繝ｻｽｧE鬯ｩ蟷｢ｽｽｽ｢髫ｰ魃会ｽｽｽｲ鬩搾ｽｵ繝ｻｽｺ驛｢譎｢ｽｽｽｻ驛｢譎｢ｽｽｽｻ郢晢ｽｻ繝ｻｽｳ鬯ｩ蟷｢ｽｽｽ｢郢晢ｽｻ繝ｻｽｧE鬯ｯｽｯ繝ｻｽｮ郢晢ｽｻ繝ｻｽ｢鬮ｯｽｷ繝ｻｽｿ郢晢ｽｻ繝ｻｽ･E鬮ｯ蜈ｷｽｽｽｹ郢晢ｽｻ繝ｻｽｺ鬮ｯｽｷ郢晢ｽｻ繝ｻｽｽ繝ｻｽｾ鬯ｩ謳ｾｽｽｽｵ郢晢ｽｻ繝ｻｽｺE鬯ｮｽｴ陷ｿ蜴ｽｽｽｻ郢ｧ謇假ｽｽｽｽ繝ｻｽｽ郢晢ｽｻ繝ｻｽ｡鬯ｮｽｫ繝ｻｽｰ郢晢ｽｻ繝ｻｽｨE鬯ｮｽｫ繝ｻｽｴ髯滓汚ｽｽｽｱ郢晢ｽｻ驍髢ｽｰ繝ｻ繝ｻ繝ｻｽ｣鬯ｩ蟷｢ｽｽｽ｢郢晢ｽｻ繝ｻｽｧ鬮ｯ蜿･ｽｹｽ｢繝ｻｽｽ繝ｻｽｵ鬩搾ｽｵ繝ｻｽｺ髫ｴ諠ｹｽｼ螟ｲｽｽｽｽ繝ｻｽｹ髫ｰ魃会ｽｽｽｲ鬩幢ｽ｢隴趣ｽ｢繝ｻｽｽ繝ｻｽｨ (鬯ｮｽｯ隲橸ｽｺ陞ｻｽｮ郢晢ｽｻ繝ｻｽｽ郢晢ｽｻ繝ｻｽｺ鬯ｮｽｫ繝ｻｽｴ髯晢ｽｷ繝ｻｽ｢郢晢ｽｻ繝ｻｽｽ郢晢ｽｻ繝ｻｽｬ30鬯ｩ蟷｢ｽｽｽ｢髫ｴ蠑ｱ繝ｻ繝ｻｽｽ繝ｻｽｼ鬯ｩｽ･郢晢ｽｻ繝ｻｽｨ隰夲ｽｵ繝ｻｽｽ繝ｻｽｹ髫ｴ雜｣ｽｽｽ｢郢晢ｽｻ繝ｻｽｽ郢晢ｽｻ繝ｻｽｼ鬯ｩ蟷｢ｽｽｽ｢驛｢譎｢ｽｽｽｻ+ 鬯ｯｽｮ繝ｻｽｴ髫ｰ繝ｻ竏槭ｻｽｽ繝ｻｽｽ郢晢ｽｻ繝ｻｽｽ鬯ｮｽｯ繝ｻｽｷ鬮｣繝ｻｽｽｽｽ郢晢ｽｻ繝ｻｽｾ髮狗ｿｫｽ代ｻｽｽ繝ｻｽｽ郢晢ｽｻ繝ｻｽ｡鬯ｮｽｫ繝ｻｽｰ郢晢ｽｻ繝ｻｽｨE鬯ｩ蟷｢ｽｽｽ｢髫ｴ蠑ｱ繝ｻ繝ｻｽｽ繝ｻｽｼ鬯ｩｽ･郢晢ｽｻ繝ｻｽｨ隰夲ｽｵ繝ｻｽｽ繝ｻｽｹ髫ｴ雜｣ｽｽｽ｢郢晢ｽｻ繝ｻｽｽ郢晢ｽｻ繝ｻｽｼ鬯ｩ蟷｢ｽｽｽ｢驛｢譎｢ｽｽｽｻ
		mnInvincibleTimer = 30 + mnUpgradeEvasionInvincibility;
	}
	if (model_->GetNowState() == ANIMATION_SLIDE)
	{
		// 鬯ｮｽｯ隲帙ｻｽｻｽｸ郢晢ｽｻ繝ｻｽｨ郢晢ｽｻ繝ｻｽ｣鬩包ｽｶ隰ｫｽｾ繝ｻｽｽ繝ｻｽｩ鬯ｯｽｯ繝ｻｽｨ郢晢ｽｻ繝ｻｽｾ鬮ｮ荵昴ｻ繝ｻｽｽ繝ｻｽｷEE鬩幢ｽ｢隴趣ｽ｢繝ｻｽｽ繝ｻｽｻ鬯ｯｽｩ陝ｶ蜷ｶ繝ｻ鬮ｫｽｴ陷ｿ蜴ｽｽｽｧ繝ｻｽｫ郢晢ｽｻ繝ｻｽｱ郢晢ｽｻ繝ｻｽｬ鬩幢ｽ｢隴趣ｽ｢繝ｻｽｽ繝ｻｽｻ鬮ｯ譎｢ｽｽｽｲ郢晢ｽｻ繝ｻｽｨ鬩包ｽｶ闔ｨ竏ｬｽｱｽｪ郢晢ｽｻ繝ｻｽｹ郢晢ｽｻ繝ｻｽｧE鬯ｩ蟷｢ｽｽｽ｢髫ｰ魃会ｽｽｽｲ鬩幢ｽ｢隴趣ｽ｢繝ｻｽｽ繝ｻｽｻ鬯ｩ蟷｢ｽｽｽ｢郢晢ｽｻ繝ｻｽｧE鬯ｩ蟷｢ｽｽｽ｢髫ｴ雜｣ｽｽｽ｢郢晢ｽｻ繝ｻｽｽ郢晢ｽｻ繝ｻｽｬ鬯ｩ蟷｢ｽｽｽ｢髫ｴ雜｣ｽｽｽ｢郢晢ｽｻ繝ｻｽｽ郢晢ｽｻ繝ｻｽｼ鬯ｩ蟷｢ｽｽｽ｢髫ｴ謇九ｻ隶夲ｽｨ鬩幢ｽ｢隴趣ｽ｢繝ｻｽｽ繝ｻｽｻ鬯ｩ蟷｢ｽｽｽ｢郢晢ｽｻ繝ｻｽｧ鬮ｯ讖ｸｽｽｽｳ髯樊ｻゑｽｽｽｲ郢晢ｽｻ繝ｻｽｽ郢晢ｽｻ繝ｻｽｶE鬯ｩ謳ｾｽｽｽｵ郢晢ｽｻ繝ｻｽｺ鬩幢ｽ｢隴趣ｽ｢繝ｻｽｽ繝ｻｽｻ
		position_ = VAdd(position_, VScale(oldmoveVec, mfEvasionSpeed + mfUpgradeEvasionSpeed));
		model_->SetPosition(position_);
		//if_StageOut();
	}






}


