	//鬯ｯｽｮ繝ｻｽｯ髫ｲ蟶吶ｻ繝ｻｽｻ繝ｻｽｸE鬩幢ｽ｢隴趣ｽ｢繝ｻｽｽ繝ｻｽｻEE鬩幢ｽ｢隴趣ｽ｢繝ｻｽｽ繝ｻｽｻE鬯ｯｽｮ繝ｻｽｯ髯具ｽｹ繝ｻｽｺ郢晢ｽｻ繝ｻｽｻ驛｢ｽｧ隰蛛ｽｽｽｽ繝ｻｽｽ郢晢ｽｻ繝ｻｽｽE鬯ｯｽｩ陝ｷｽ｢繝ｻｽｽ繝ｻｽ｢E鬯ｮｽｯ隶厄ｽｸ繝ｻｽｽ繝ｻｽｳ鬮ｯ讓奇ｽｻ繧托ｽｽｽｽ繝ｻｽｲEE鬩幢ｽ｢隴趣ｽ｢繝ｻｽｽ繝ｻｽｻE鬯ｯｽｮ繝ｻｽｯ髫ｶ蜴ｽｽｽｸ郢晢ｽｻ繝ｻｽｽ郢晢ｽｻ繝ｻｽｳ鬯ｩ蟷｢ｽｽｽ｢髫ｴ雜｣ｽｽｽ｢郢晢ｽｻ繝ｻｽｽ郢晢ｽｻ繝ｻｽｻ
	rotation_.y = mfAngle + DX_PI_F;
	//鬯ｯｽｩ陝ｷｽ｢繝ｻｽｽ繝ｻｽ｢鬮ｫｽｴ髮懶ｽ｣繝ｻｽｽ繝ｻｽ｢EE鬯ｯｽｩ陝ｷｽ｢繝ｻｽｽ繝ｻｽ｢鬮ｫｽｴ隰ｫｽｾ繝ｻｽｽ繝ｻｽｴ鬩幢ｽ｢隴趣ｽ｢繝ｻｽｽ繝ｻｽｻE鬮ｫｽｴ闕ｳｽｻ隰ｽｿE鬩幢ｽ｢隴趣ｽ｢繝ｻｽｽ繝ｻｽｻE鬯ｯｽｮ繝ｻｽ｣鬮ｮ蜈ｷｽｽｽｻ郢晢ｽｻ繝ｻｽｽ郢晢ｽｻ繝ｻｽｨ鬯ｮｽｫ繝ｻｽｴ髫ｰｽｫ繝ｻｽｾ郢晢ｽｻ繝ｻｽｽ郢晢ｽｻ繝ｻｽｴ鬯ｩ蛹ｽｽｽｶ髫ｰｽｫ繝ｻｽｾ郢晢ｽｻ繝ｻｽｽ郢晢ｽｻ繝ｻｽｴ鬯ｯｽｩ陝ｷｽ｢繝ｻｽｽ繝ｻｽ｢E鬯ｩ蟷｢ｽｽｽ｢髫ｴ雜｣ｽｽｽ｢郢晢ｽｻ繝ｻｽｽ郢晢ｽｻ繝ｻｽｻ
	model_->SetRotation(rotation_);

	////鬯ｯｽｮ繝ｻｽｯ髫ｲ蟶吶ｻ繝ｻｽｻ繝ｻｽｸE鬩幢ｽ｢隴趣ｽ｢繝ｻｽｽ繝ｻｽｻEE鬩幢ｽ｢隴趣ｽ｢繝ｻｽｽ繝ｻｽｻE鬯ｯｽｮ繝ｻｽｯ髯具ｽｹ繝ｻｽｺ郢晢ｽｻ繝ｻｽｻ驛｢ｽｧ隰蛛ｽｽｽｽ繝ｻｽｽ郢晢ｽｻ繝ｻｽｽE鬯ｯｽｩ陝ｷｽ｢繝ｻｽｽ繝ｻｽ｢E鬯ｮｽｯ隶厄ｽｸ繝ｻｽｽ繝ｻｽｳ鬮ｯ讓奇ｽｻ繧托ｽｽｽｽ繝ｻｽｲEE鬩幢ｽ｢隴趣ｽ｢繝ｻｽｽ繝ｻｽｻE鬯ｯｽｮ繝ｻｽｯ髫ｶ蜴ｽｽｽｸ郢晢ｽｻ繝ｻｽｽ郢晢ｽｻ繝ｻｽｳ鬯ｩ蟷｢ｽｽｽ｢髫ｴ雜｣ｽｽｽ｢郢晢ｽｻ繝ｻｽｽ郢晢ｽｻ繝ｻｽｻ
	////鬯ｯｽｩ陝ｷｽ｢繝ｻｽｽ繝ｻｽ｢鬮ｫｽｴ髮懶ｽ｣繝ｻｽｽ繝ｻｽ｢EE鬯ｯｽｩ陝ｷｽ｢繝ｻｽｽ繝ｻｽ｢鬮ｫｽｴ隰ｫｽｾ繝ｻｽｽ繝ｻｽｴ鬩幢ｽ｢隴趣ｽ｢繝ｻｽｽ繝ｻｽｻE鬮ｫｽｴ闕ｳｽｻ隰ｽｿE鬩幢ｽ｢隴趣ｽ｢繝ｻｽｽ繝ｻｽｻE鬯ｯｽｮ繝ｻｽ｣鬮ｮ蜈ｷｽｽｽｻ郢晢ｽｻ繝ｻｽｽ郢晢ｽｻ繝ｻｽｨ鬯ｮｽｫ繝ｻｽｴ髫ｰｽｫ繝ｻｽｾ郢晢ｽｻ繝ｻｽｽ郢晢ｽｻ繝ｻｽｴ鬯ｩ蛹ｽｽｽｶ髫ｰｽｫ繝ｻｽｾ郢晢ｽｻ繝ｻｽｽ郢晢ｽｻ繝ｻｽｴ鬯ｯｽｩ陝ｷｽ｢繝ｻｽｽ繝ｻｽ｢E鬯ｩ蟷｢ｽｽｽ｢髫ｴ雜｣ｽｽｽ｢郢晢ｽｻ繝ｻｽｽ郢晢ｽｻ繝ｻｽｻ


