		model_->ChangeAnimation(ANIMATION_ATTACKJUMP);
		//鬯ｯｽｩ陝ｷｽ｢繝ｻｽｽ繝ｻｽ｢鬮ｫｽｴ髮懶ｽ｣繝ｻｽｽ繝ｻｽ｢EE鬯ｯｽｩ陝ｷｽ｢繝ｻｽｽ繝ｻｽ｢鬮ｫｽｴ髮懶ｽ｣繝ｻｽｽ繝ｻｽ｢EE鬯ｯｽｩ陝ｷｽ｢繝ｻｽｽ繝ｻｽ｢鬮ｫｽｴ隲ｽｹ繝ｻｽｸ隶厄ｽｸ繝ｻｽｽ繝ｻｽｹ郢晢ｽｻ繝ｻｽｲ鬯ｩ蟷｢ｽｽｽ｢髫ｴ雜｣ｽｽｽ｢郢晢ｽｻ繝ｻｽｽ郢晢ｽｻ繝ｻｽｻ鬯ｯｽｩ隰ｳｽｾ繝ｻｽｽ繝ｻｽｵE鬯ｯｽｮ繝ｻｽｴ髯懈瑳ｽｺｽｷ驛｢ｽｭ鬯ｯｽｮ繝ｻｽｮ郢晢ｽｻ繝ｻｽｷ鬯ｯｽｩ隰ｳｽｾ繝ｻｽｽ繝ｻｽｵE鬩幢ｽ｢隴趣ｽ｢繝ｻｽｽ繝ｻｽｻE鬯ｯｽｩ隰ｳｽｾ繝ｻｽｽ繝ｻｽｵE鬯ｩ蟷｢ｽｽｽ｢髫ｴ雜｣ｽｽｽ｢郢晢ｽｻ繝ｻｽｽ郢晢ｽｻ繝ｻｽｻ
		model_->SetLoop(false);
