void Player3D::OnEnter(Collider* collider, Collider* check)
{
	

	if (collider == mpSerchEnemyCollider && check->parent_object_->GetTag() == Object3D::Tag3D_Enemy3D)
	{
		

		auto pEne = check->parent_object_->CastTo<Enemy>();
		if (pEne == nullptr) return;
		VECTOR mnEneDistance = VSub(pEne->GetPosition(), position_);
		if (check == pEne->GetEnemycoll())
		{
			mbAttackSlideSerch = true;
			float VECSize = VSize(mnEneDistance);
			FirstNearVec++;
			if (FirstNearVec == 1)
			{
				VECSizeFirst = VECSize;
			}

			if (VECSizeFirst <= VECSize)
			{
				VECSizeFirst = VECSize;
				target_ = pEne;

			}
		}
	}


	if (collider == mpCapsuleCollider && check->parent_object_->GetTag() == Tag3D_Obj)
	{
		position_ = old_position_;//object縺ｫ蠖薙◆縺｣縺溘ｉ縺ｲ縺ｨ縺､蜑阪↓謌ｻ繧
	}

}

void Player3D::OnTrigger(Collider* collider, Collider* check)
{

	AnimationState now = model_->GetNowState();

	if (now == ANIMATION_ATTACK)
	{
		if (collider == mpAttachCollider && check->parent_object_->GetTag() == Object3D::Tag3D_Enemy3D)
		{
			Enemy* pEne = check->parent_object_->CastTo<Enemy>();
			if (pEne == nullptr) return;
			if (check == pEne->GetEnemycoll())
			{
				
				// 鬯ｯｽｮ繝ｻｽｫEE鬩幢ｽ｢隴趣ｽ｢繝ｻｽｽ繝ｻｽｻE鬯ｯｽｮ繝ｻｽｫEE鬯ｩ蟷｢ｽｽｽ｢髫ｴ雜｣ｽｽｽ｢EEE鬯ｨｽｾ繝ｻｽｧEE鬮ｫｽｴ髮懶ｽ｣繝ｻｽｽ繝ｻｽ｢EE鬯ｯｽｩ陝ｷｽ｢繝ｻｽｽ繝ｻｽ｢E鬩幢ｽ｢隴趣ｽ｢繝ｻｽｽ繝ｻｽｻE鬯ｯｽｩ陝ｷｽ｢繝ｻｽｽ繝ｻｽ｢鬮ｫｽｴ髮懶ｽ｣繝ｻｽｽ繝ｻｽ｢EE鬯ｯｽｩ陝ｷｽ｢繝ｻｽｽ繝ｻｽ｢鬮ｫｽｴ髮懶ｽ｣繝ｻｽｽ繝ｻｽ｢EE&&Attack1
				if (now == ANIMATION_ATTACK && AttackState == Attack_Normal && !mbjump && !pEne->GetHitjudgment())
				{
					
					pEne->Damage(GetAllStatusState(Object3D::Status_Attack));
					// 鬯ｯｽｯ繝ｻｽｨE鬮ｯ蜈ｷｽｽｽｹ驛｢譎｢ｽｽｽｻE鬯ｯｽｯ繝ｻｽｯEE鬩幢ｽ｢隴趣ｽ｢繝ｻｽｽ繝ｻｽｻE鬯ｯｽｮ繝ｻｽｫEE鬩幢ｽ｢隴趣ｽ｢繝ｻｽｽ繝ｻｽｻE鬯ｯｽｩ陝ｷｽ｢繝ｻｽｽ繝ｻｽ｢E鬯ｮｽｯ雋顔§謫E髣費ｽｨ陞滂ｽｲ繝ｻｽｽ繝ｻｽｽE鬩幢ｽ｢隴趣ｽ｢繝ｻｽｽ繝ｻｽｻEE鬯ｮｽｯ隴趣ｽ｢繝ｻｽｽ繝ｻｽｶ鬮ｯｽｷ繝ｻｽｻEE鬩幢ｽ｢隴趣ｽ｢繝ｻｽｽ繝ｻｽｻ
					Master::mpCamera->SetupShake(5.0f, 10.0f, 5.0f);
					EffectPool::GetInstance()->Play(VAdd(pEne->GetPosition(), VGet(0.0f, 60.0f, 0.0f)), "Resource/Damage.png", GetColorU8(255, 0, 30, 0), 30.0f, 0.1f);
				}


			}

		}
	}
	if (collider == mpAttackJumpCollider && check->parent_object_->GetTag() == Tag3D_Enemy3D)
	{
		Enemy* pEne = check->parent_object_->CastTo<Enemy>();
		if (pEne == nullptr) return;
		if (check == pEne->GetEnemycoll())
		{
			if (now == ANIMATION_ATTACKJUMP && AttackState == Attack_Jump && !pEne->GetHitjudgment())
			{
				pEne->SetHitjudgment(true);
				pEne->Damage(GetAllStatusState(Object3D::Status_Attack) + mfAttackjump);

				// 鬯ｯｽｯ繝ｻｽｨ郢晢ｽｻ繝ｻｽｾ鬮ｯ蜈ｷｽｽｽｹ驛｢譎｢ｽｽｽｻE鬯ｯｽｯ繝ｻｽｯ郢晢ｽｻ繝ｻｽｮE鬩幢ｽ｢隴趣ｽ｢繝ｻｽｽ繝ｻｽｻE鬯ｯｽｮ繝ｻｽｫ郢晢ｽｻ繝ｻｽｰE鬩幢ｽ｢隴趣ｽ｢繝ｻｽｽ繝ｻｽｻE鬯ｯｽｩ陝ｷｽ｢繝ｻｽｽ繝ｻｽ｢E鬯ｮｽｯ雋顔§謫郢晢ｽｻ繝ｻｽｯ髣費ｽｨ陞滂ｽｲ繝ｻｽｽ繝ｻｽｽ郢晢ｽｻ繝ｻｽｼ鬩幢ｽ｢隴趣ｽ｢繝ｻｽｽ繝ｻｽｻEE鬯ｮｽｯ隴趣ｽ｢繝ｻｽｽ繝ｻｽｶ鬮ｯｽｷ繝ｻｽｻ郢晢ｽｻ繝ｻｽｻE鬩幢ｽ｢隴趣ｽ｢繝ｻｽｽ繝ｻｽｻ
				Master::mpCamera->SetupShake(5.0f, 10.0f, 5.0f);
				
			}
		}
	}

	if (collider == mpAttackSlideCollider && check->parent_object_->GetTag() == Tag3D_Enemy3D)
	{
		Enemy* pEne = check->parent_object_->CastTo<Enemy>();
		if (pEne == nullptr) return;
		if (check == pEne->GetEnemycoll())
		{
			if (now == ANIMATION_ATTACKSLIDE && AttackState == Attack_Slide && !pEne->GetHitjudgment())
			{
				pEne->Damage(GetAllStatusState(Object3D::Status_Attack) + mfAttackSlide);
				pEne->SetHitjudgment(true);
				// 鬯ｯｽｯ繝ｻｽｨ郢晢ｽｻ繝ｻｽｾ鬮ｯ蜈ｷｽｽｽｹ驛｢譎｢ｽｽｽｻE鬯ｯｽｯ繝ｻｽｯ郢晢ｽｻ繝ｻｽｮE鬩幢ｽ｢隴趣ｽ｢繝ｻｽｽ繝ｻｽｻE鬯ｯｽｮ繝ｻｽｫ郢晢ｽｻ繝ｻｽｰE鬩幢ｽ｢隴趣ｽ｢繝ｻｽｽ繝ｻｽｻE鬯ｯｽｩ陝ｷｽ｢繝ｻｽｽ繝ｻｽ｢E鬯ｮｽｯ雋顔§謫郢晢ｽｻ繝ｻｽｯ髣費ｽｨ陞滂ｽｲ繝ｻｽｽ繝ｻｽｽ郢晢ｽｻ繝ｻｽｼ鬩幢ｽ｢隴趣ｽ｢繝ｻｽｽ繝ｻｽｻEE鬯ｮｽｯ隴趣ｽ｢繝ｻｽｽ繝ｻｽｶ鬮ｯｽｷ繝ｻｽｻ郢晢ｽｻ繝ｻｽｻE鬩幢ｽ｢隴趣ｽ｢繝ｻｽｽ繝ｻｽｻ
				Master::mpCamera->SetupShake(5.0f, 10.0f, 5.0f);
				EffectPool::GetInstance()->Play(VAdd(pEne->GetPosition(), VGet(0.0f, 60.0f, 0.0f)), "Resource/Damage.png", GetColorU8(35, 0, 255, 0), 60.0f, 1.0f);
			}
		}
	}
	


}
void Player3D::mpTargetOn()
{
	if (target_ != nullptr)
	{
		bool isTargetValid = false;
		const auto& mpEneList = Master::mpSceneManager->GetCurrentScene()->GetObjectManager()->GetObject3DListByTag(Object3D::Tag3D_Enemy3D);
		for (int i = 0; i < mpEneList.size(); i++)
		{
			if (target_ == mpEneList.at(i) && !target_->IsDeleteFlag())
			{
				isTargetValid = true;
				break;
			}
		}
		if (!isTargetValid)
		{
			target_ = nullptr;
		}
	}
}

